# Create a schema map: all node types, all edge types, and which node types each edge type can connect.

# Extract all node types and their ids
node_id_to_type = {}
node_types = set()
for node in data.get("nodes", []):
    node_type = node.get("Node Type")
    if node_type:
        node_types.add(node_type)
    node_id = node.get("id")
    if node_id is not None:
        node_id_to_type[node_id] = node_type

# Extract all edge types and the node type pairs they connect
edge_types = set()
edge_type_links = {}

for link in data.get("links", []):
    edge_type = link.get("Edge Type")
    source = link.get("source")
    target = link.get("target")
    source_type = node_id_to_type.get(source, "Unknown")
    target_type = node_id_to_type.get(target, "Unknown")
    edge_types.add(edge_type)
    if edge_type not in edge_type_links:
        edge_type_links[edge_type] = set()
    edge_type_links[edge_type].add((source_type, target_type))

# Print schema map
print("\n=== NODE TYPES ===")
for nt in sorted(node_types):
    print(f"- {nt}")

print("\n=== EDGE TYPES AND CONNECTIVITY ===")
for etype in sorted(edge_types):
    print(f"\nEdge Type: '{etype}'")
    for src_t, tgt_t in sorted(edge_type_links[etype]):
        print(f"  {src_t} --> {tgt_t}")

